def process_payment(method, amount, details):
    if method == 'credit_card':
        card = details['card_number']
        # Validate card
        if not validate_luhn(card):
            raise ValueError('Invalid card')
        # Charge card
        result = stripe.charge(card, amount)
        return {'success': True, 'transaction_id': result.id}

    elif method == 'paypal':
        email = details['paypal_email']
        # Create PayPal payment
        result = paypal.create_payment(email, amount)
        return {'success': True, 'redirect_url': result.approval_url}

    elif method == 'crypto':
        wallet = details['wallet_address']
        # Generate crypto invoice
        invoice = crypto.create_invoice(wallet, amount)
        return {'success': True, 'invoice_url': invoice.url}

    else:
        raise ValueError(f'Unknown payment method: {method}')

